using MachinesDataAnalyzingSystem.ClientWebApp.ServiceContracts;
using MachinesDataAnalyzingSystem.Shared.DTO.Machine;
using Microsoft.AspNetCore.Components;
using Microsoft.JSInterop;
using MudBlazor;
using System.Net;
using System.Text.Json;

namespace MachinesDataAnalyzingSystem.ClientWebApp.Components.Controls.Home;

public partial class MachinesNavMenuComponent(IWebAPIService webAPIService, ISnackbar snackbar, NavigationManager navigationManager)
{
    private List<MachineResponse> _machines = [];

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if(!firstRender)
        {
            return;
        }

        try
        {
            var response = await webAPIService.SendAsync(HttpMethod.Get, "/api/machines");
            response.EnsureSuccessStatusCode();
            _machines = await response.Content.ReadFromJsonAsync<List<MachineResponse>>();
            StateHasChanged();
        }
        catch(HttpRequestException e)
        {
            if(e.StatusCode is null)
            {
                snackbar.Add("Server is unavailable. Please try later.", Severity.Error);
            }
            else if(e.StatusCode == HttpStatusCode.Unauthorized)
            {
                navigationManager.NavigateTo("/Logout");
            }
            else
            {
                snackbar.Add($"HTTP error with status code: {e.StatusCode.ToString()}", Severity.Error);
            }
        }
    }
}